from pathlib import Path
import json,re,html
root=Path(__file__).resolve().parents[1]
out=root/'wireframes'
data=json.loads((root/'research/catalogue/designs.json').read_text(encoding='utf-8'))
for r in data:
    text=(root/'research/catalogue'/r['source'].replace('.pdf','.txt')).read_text(encoding='utf-8')
    page=text.split('PAGE '+str(r['pdf_page'])+'\n',1)[1].split('\nPAGE ',1)[0]
    r['offer']='Jali & partitions' if not r['code'].startswith('AMF-3DR') else 'Sculpted wall art' if r['category']=='SCULPTED WALL ART' else 'Carved doors' if 'door' in page.split('COMMON APPLICATIONS')[-1].split('FINISH OPTIONS')[0].lower() else 'Relief wall panels'
    r['preview']=next((i['path'] for i in r['images'] if i['width']>1300 and i['height']>1400),r['images'][0]['path'])
    r['name']=r['name'].title()
offers=['Jali & partitions','Carved doors','Relief wall panels','Sculpted wall art']
sample=['AMF-GEO-01','AMF-3DR-01','AMF-3DR-17','AMF-3DR-30']
home=(out/'home.html').read_text(encoding='utf-8')
start=home.index('<section id="choose">');end=home.index('<section><h2>Cut through.',start)
sections='<section id="choose"><p class="eyebrow">OUR COLLECTIONS</p><h2>Four ways to make it your own.</h2><p>Explore jali patterns, carved doors, textured panels and sculpted art. Choose a catalogue design or bring a reference.</p>'
for idx,(offer,code) in enumerate(zip(offers,sample)):
    r=next(r for r in data if r['code']==code)
    desc=['Open patterns for decorative panels and partitions.','Surface-carved designs for suitable door blanks.','Carved textures and compositions for feature walls.','Devotional, botanical and figurative relief compositions.'][idx]
    sections+=f'<article class="feature {"reverse" if idx%2 else ""}"><figure><img src="../{r["preview"]}" alt="{r["name"]} catalogue reference" loading="lazy" width="1507" height="1627"><figcaption>{r["name"]} · {code} · Catalogue illustration</figcaption></figure><div><h3>{offer}</h3><p>{desc}</p><a class="button" href="catalogue.html?offer={html.escape(offer)}">View {offer.lower()}</a><p><a href="quote.html?design={code}">Get a Quote on WhatsApp</a></p></div></article>'
sections+='</section><section><p class="eyebrow">THE DESIGN CATALOGUE</p><h2>Find your pattern.</h2><p>54 catalogue designs across decorative CNC panels and 3D relief. Search by name or AMF code, or explore a collection.</p><a class="button primary" href="catalogue.html">View all designs</a><div class="category-list"><a class="category" href="../catalogue/A.S.%20Metal%20Fabricators%20-%20Decorative%20CNC%20Panel%20Catalogue.pdf">Decorative CNC panels PDF <span>29 designs · 43 MB</span></a><a class="category" href="../catalogue/A.S%20Metal%20Fabricators%20-%203D%20Relief%20Catalogue.pdf">3D relief PDF <span>25 designs · 33 MB</span></a></div></section><section><h2>Custom cutting & carving.</h2><p>Bring your sketch, design reference or suitable board. Share the material type, grade, thickness and dimensions for review.</p><div class="category-list"><div><h3>Cutting capacity</h3><p>3-axis CNC routing with 4 × 8 ft and 6 × 12 ft beds. These are machine capacities; finished dimensions are reviewed per project.</p></div><div><h3>Boards & sheet enquiries</h3><p>MDF, HDF and HDHMR options. ACP, aluminium and HPL Compact are reviewed for feasibility; customer-supplied sheets are preferred.</p></div><div><h3>Finish options</h3><p>Raw or primed; Duco by arrangement; suitable laminated 2D boards; relief colour matching by request.</p></div></div><a class="button primary" href="quote.html">Get a Quote on WhatsApp</a></section>'
home=home[:start]+sections+home[end:]
(out/'home.html').write_text(home,encoding='utf-8')
cards=''
for r in data:
    cards+=f'<article class="catalogue-card" data-offer="{html.escape(r["offer"])}" data-family="{html.escape(r["category"])}" data-search="{html.escape(r["name"]+" "+r["code"])}"><img src="../{r["preview"]}" loading="lazy" alt="{r["name"]} catalogue illustration"><small>Catalogue illustration · {r["code"]}</small><h3>{r["name"]}</h3><p>{r["offer"]} · {r["category"].title()}</p><a class="button" href="quote.html?design={r["code"]}">Quote this design</a></article>'
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catalogue structure · Phase 2 wireframe</title><link rel="stylesheet" href="style.css"><style>.catalogue-grid{display:grid;gap:32px}.catalogue-card img{height:300px;object-fit:contain;background:var(--surface)}.catalogue-card{min-width:0}.catalogue-card h3{font-size:24px}@media(min-width:650px){.catalogue-grid{grid-template-columns:repeat(2,1fr)}}@media(min-width:1000px){.catalogue-grid{grid-template-columns:repeat(3,1fr)}}</style><header><div class="wrap"><a class="brand" href="home.html">A.S Metal Fabricators</a><a href="quote.html">WhatsApp Quote</a></div></header><main class="wrap"><section><p class="eyebrow">CATALOGUE STRUCTURE WIREFRAME</p><h1>Find a design for your space.</h1><p>Browse the full catalogue or bring your own reference. Materials, dimensions and finishes are confirmed for each project.</p><label>Search name or AMF code<input id="search" type="search"></label><div class="form-grid"><label>Offering<select id="offer"><option value="">All offerings</option>'''+''.join('<option>'+html.escape(o)+'</option>' for o in offers)+'''</select></label><label>Pattern family<select id="family"><option value="">All families</option>'''+''.join('<option>'+html.escape(o)+'</option>' for o in sorted(set(r['category'] for r in data)))+'''</select></label></div><button id="reset">Clear filters</button><p id="count" role="status"></p><p id="empty" hidden>No matching designs. Clear filters or <a href="quote.html">send your own reference</a>.</p><div class="catalogue-grid">'''+cards+'''</div></section><section><h2>Have your own design?</h2><a class="button primary" href="quote.html">Get a Quote on WhatsApp</a></section></main><footer class="wrap">Built by ExpandR · Demo</footer><script src="shared.js"></script><script>const search=document.getElementById('search'),offer=document.getElementById('offer'),family=document.getElementById('family');if([...offer.options].some(o=>o.value===params.get('offer')))offer.value=params.get('offer');function filter(){let n=0;document.querySelectorAll('.catalogue-card').forEach(c=>{c.hidden=!!((offer.value&&c.dataset.offer!==offer.value)||(family.value&&c.dataset.family!==family.value)||!c.dataset.search.toLowerCase().includes(search.value.toLowerCase().trim()));if(!c.hidden)n++});document.getElementById('count').textContent=n+' designs';document.getElementById('empty').hidden=n!==0}search.oninput=offer.onchange=family.onchange=filter;document.getElementById('reset').onclick=()=>{search.value=offer.value=family.value='';filter()};filter();</script></html>'''
(out/'catalogue.html').write_text(page,encoding='utf-8')
js=(out/'shared.js').read_text(encoding='utf-8')
js=re.sub(r"const names=\{[^;]+;",'const names='+json.dumps({r['code']:r['name'] for r in data})+';',js)
js=js.replace('(home|quote)', '(home|quote|catalogue)')
(out/'shared.js').write_text(js,encoding='utf-8')
for name in ['index.html','revised.html']:
    p=out/name;s=p.read_text(encoding='utf-8');s=s.replace('<button data-page="quote"','<button data-page="catalogue" aria-pressed="false">Catalogue</button><button data-page="quote"');p.write_text(s,encoding='utf-8')
print({o:sum(r['offer']==o for r in data) for o in offers})
